mapper.select:
SELECT s.id, s.tenant_id, s.bus_no, s.name, s.py_str, s.wb_str, s.type_enum, s.status_enum, s.updated_at FROM adm_specimen_definition s
s.is_deleted = 0 AND s.tenant_id = #{tenantId}
AND (s.name LIKE CONCAT('%', #{query.keyword}, '%') OR s.bus_no LIKE CONCAT('%', #{query.keyword}, '%') OR s.py_str LIKE CONCAT('%', #{query.keyword}, '%') OR s.wb_str LIKE CONCAT('%', #{query.keyword}, '%'))
AND s.type_enum = #{query.typeEnum}
AND s.status_enum = #{query.statusEnum}
ORDER BY s.updated_at DESC, s.id DESC
